fn mark_agent_dirty(dir:&std::path::Path)->std::io::Result<()> {
 use std::io::Write;use std::os::unix::fs::{OpenOptionsExt,MetadataExt};
 let path=dir.join(".atlas-agent-index-dirty");
 match std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&path){
  Ok(mut file)=>{file.write_all(b"pending")?;file.sync_all()?;std::fs::File::open(dir)?.sync_all()},
  Err(e) if e.kind()==std::io::ErrorKind::AlreadyExists=>{let m=std::fs::symlink_metadata(path)?;if !m.is_file()||m.file_type().is_symlink()||m.nlink()!=1||m.uid()!=unsafe{libc::geteuid()}{return Err(std::io::Error::new(std::io::ErrorKind::PermissionDenied,"unsafe indexing marker"))}Ok(())},Err(e)=>Err(e)
 }
}
