fn read_preview_text_size(dir:&std::path::Path)->u64 {std::fs::read_to_string(dir.join("preview-text-size")).ok().and_then(|v|v.parse::<u64>().ok()).filter(|v|(10..=32).contains(v)).unwrap_or(16)}
