mod recovery_contract {
 use super::*;
 #[test]
 fn restores_absent_workspace_but_never_overwrites_existing() {
  let root=std::env::temp_dir().join(format!("atlas-recover-test-{}",uuid::Uuid::new_v4().simple()));
  std::fs::create_dir(&root).unwrap();
  let id="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"; let nonce="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
  let backup=root.join(format!(".atlas-unprotected-{id}-{nonce}"));
  std::fs::create_dir(&backup).unwrap();std::fs::write(backup.join(".atlas-owned"),"atlas-workspace-v1").unwrap();std::fs::write(backup.join("content"),"original").unwrap();
  recover_conversion(&root,None).unwrap();assert_eq!(std::fs::read_to_string(root.join(id).join("content")).unwrap(),"original");
  std::fs::create_dir(&backup).unwrap();std::fs::write(backup.join(".atlas-owned"),"atlas-workspace-v1").unwrap();std::fs::write(backup.join("content"),"backup").unwrap();
  recover_conversion(&root,None).unwrap();assert_eq!(std::fs::read_to_string(root.join(id).join("content")).unwrap(),"original");assert!(backup.exists());
  std::fs::remove_dir_all(root).unwrap();
 }
}
