#[cfg(all(test,feature="agent-write",not(feature="test-hook")))]
mod agent_write_di_tests {
 use super::*;
 use std::io::{Read,Write};
 use std::sync::{Arc,Mutex,OnceLock};
 #[test]
 fn isolated_four_workspace_types_create_and_replay() {
  let root=std::env::temp_dir().join(format!("atlas-agent-di-{}",uuid::Uuid::new_v4().simple()));std::fs::create_dir(&root).unwrap();let root=root.canonicalize().unwrap();
  let default=root.join("default");call("create-workspace",&default,&[]).unwrap();
  let protected=Arc::new(protected::Protected::new());let p=protected.create(&root,"Protected","test-password").unwrap();let pid=p["id"].as_str().unwrap().to_string();
  let profile=agent_profiles::dispatch(&root,"POST",None,Some(json!({"name":"test"}))).unwrap().1;let id=profile["id"].as_str().unwrap();let token=profile["token"].as_str().unwrap().to_owned();
  agent_profiles::dispatch(&root,"PUT",Some(id),Some(json!({"name":"test","permissions":{"default":{"read":true,"add":true,"edit":true},pid.clone():{"read":true,"add":true,"edit":true}}}))).unwrap();
  let workers=Arc::new(workspace_worker::Workers::default());
  let worker_binary=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("target/debug/atlas-native-http");assert!(worker_binary.is_file(),"build production backend before running DI tests");workspace_worker::set_test_worker_executable(worker_binary);
  let external_id="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";let encrypted_id="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
  let external=root.join("external-plain");call("create-workspace",&external,&[]).unwrap();workers.attach(external_id,&std::fs::File::open(&external).unwrap(),&external).unwrap();
  let encrypted=root.join("external-protected");std::fs::create_dir(&encrypted).unwrap();{let mut vault=atlas_sqlcipher_proof::Vault::create(&encrypted.join("workspace.atlas"),"test-password").unwrap();vault.set_workspace_name("Protected external").unwrap();}std::fs::write(encrypted.join(".atlas-protected"),b"atlas-protected-v1").unwrap();std::fs::write(encrypted.join(".workspace.json"),r#"{"name":"Protected external"}"#).unwrap();workers.attach_protected_for_test(encrypted_id,&std::fs::File::open(&encrypted).unwrap(),&encrypted).unwrap();workers.request(encrypted_id,&json!({"action":"unlock","password":"test-password"})).unwrap();
  agent_profiles::dispatch(&root,"PUT",Some(id),Some(json!({"name":"test","permissions":{"default":{"read":true,"add":true,"edit":true},pid.clone():{"read":true,"add":true,"edit":true},external_id:{"read":true,"add":true,"edit":true},encrypted_id:{"read":true,"add":true,"edit":true}}}))).unwrap();
  let model=Mutex::new(ModelState::Disabled);let states=Arc::new(Mutex::new(std::collections::HashMap::new()));let choice=ModelChoice{exe:String::new(),dir:root.clone(),selected:Mutex::new("e2b".into()),warning:Mutex::new(None),default_embedding_variant:OnceLock::new()};let device=device::DeviceSettings::new(root.clone(),String::new());let rag=Mutex::new(RagState::Disabled);
  let request=|method:&str,path:&str,credential:&str,value:Option<Value>|->(u16,Value){let (mut client,server)=std::os::unix::net::UnixStream::pair().unwrap();let body=value.map(|v|v.to_string()).unwrap_or_default();write!(client,"{method} {path} HTTP/1.1\r\nHost: localhost\r\nX-Atlas-Agent-Token: {credential}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{body}",body.len()).unwrap();let req=agent_socket::parse_test(server).unwrap();agent_request(req,&root,&default,&workers,&protected,&model,&states,&choice,&device,&rag);let mut response=String::new();client.read_to_string(&mut response).unwrap();let (head,body)=response.split_once("\r\n\r\n").unwrap();(head.split_whitespace().nth(1).unwrap().parse().unwrap(),serde_json::from_str(body).unwrap())};
  for wid in ["default",pid.as_str(),external_id,encrypted_id] {
   let path=format!("/api/agent/{wid}/notes");let input=json!({"title":"Title","text":"body","request_id":"same"});
   assert_eq!(request("POST",&path,"invalid",Some(input.clone())).0,403);
   let (code,first)=request("POST",&path,&token,Some(input.clone()));assert_eq!(code,201,"{first}");let (code,replay)=request("POST",&path,&token,Some(input));assert_eq!(code,201,"{replay}");assert_eq!(replay["id"],first["id"]);assert_eq!(replay["replayed"],true);
   let note=first["id"].as_str().unwrap();let get=format!("{path}/{note}");assert_eq!(request("GET",&get,&token,None).1["text"],"body");
   let edit=format!("{get}/edit");let(code,lease)=request("POST",&edit,&token,Some(json!({"action":"acquire"})));assert_eq!(code,200,"{lease}");let(code,busy)=request("POST",&edit,&token,Some(json!({"action":"acquire"})));assert_eq!(code,409,"{busy}");let secret=lease["lease"].as_str().unwrap();let(code,commit)=request("POST",&edit,&token,Some(json!({"action":"commit","lease":secret,"title":"Changed","text":"updated"})));assert_eq!(code,200,"{commit}");assert_eq!(request("GET",&get,&token,None).1["text"],"updated");assert_eq!(request("POST",&edit,&token,Some(json!({"action":"release","lease":secret}))).0,200);
  }
  agent_profiles::dispatch(&root,"DELETE",Some(id),None).unwrap();assert_eq!(request("GET","/api/agent/default/notes/anything",&token,None).0,403);
  workers.detach_and_wait_for_test(external_id).unwrap();workers.detach_and_wait_for_test(encrypted_id).unwrap();drop(workers);drop(protected);std::fs::remove_dir_all(root).unwrap();
 }
}

